methods.body:
if (socialSecurityNumber == null || socialSecurityNumber.isBlank() || name == null || name.isBlank()
        || email == null || !email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))
    throw new IllegalArgumentException("Нужны социальный код, имя и корректный e-mail");
this.socialSecurityNumber = socialSecurityNumber.strip();
this.name = name.strip();
this.email = email.strip();

this.faculty = Objects.requireNonNull(faculty);
if (name == null || name.isBlank() || address == null || address.isBlank())
    throw new IllegalArgumentException("Нужны название и адрес кафедры");
this.name = name.strip();
this.address = address.strip();

this.university = Objects.requireNonNull(university);
if (name == null || name.isBlank()) throw new IllegalArgumentException("Нужно название факультета");
this.name = name.strip();

if (institutes.stream().anyMatch(i -> i.getName().equals(name == null ? "" : name.strip())))
    throw new IllegalArgumentException("Кафедра уже существует");
Institute institute = new Institute(this, name, address);
institutes.add(institute);
return institute;

if (!university.getEmployees().contains(employee))
    throw new IllegalArgumentException("Декан должен быть сотрудником этого университета");
if (university.getFaculties().stream().anyMatch(f -> f != this && f.getDean() == employee))
    throw new IllegalArgumentException("Сотрудник уже является деканом другого факультета");
dean = employee;

if (name == null || name.isBlank() || startingDate == null || endDate == null || endDate.isBefore(startingDate))
    throw new IllegalArgumentException("Нужны название и даты проекта: начало <= окончание");
this.name = name.strip();
this.startingDate = startingDate;
this.endDate = endDate;

this.employee = Objects.requireNonNull(employee);
this.project = Objects.requireNonNull(project);
if (hours <= 0) throw new IllegalArgumentException("Часы участия должны быть положительными");
this.hours = hours;

super(socialSecurityNumber, name, email);
if (researchArea == null || researchArea.isBlank()) throw new IllegalArgumentException("Нужна область исследований");
this.researchArea = researchArea.strip();
institutes.add(Objects.requireNonNull(institute));

Objects.requireNonNull(institute);
University university = institutes.iterator().next().getFaculty().getUniversity();
if (institute.getFaculty().getUniversity() != university)
    throw new IllegalArgumentException("Кафедра другого университета");
institutes.add(institute);

if (participations.stream().anyMatch(p -> p.getProject() == project))
    throw new IllegalArgumentException("Сотрудник уже участвует в проекте");
Participation participation = new Participation(this, project, hours);
participations.add(participation);
return participation;

if (id == null || id.isBlank() || name == null || name.isBlank() || weeklyDuration <= 0)
    throw new IllegalArgumentException("Нужны ID, название и положительная недельная нагрузка курса");
this.id = id.strip();
this.name = name.strip();
this.weeklyDuration = weeklyDuration;
lecturers.add(Objects.requireNonNull(lecturer));

if (!course.getLecturers().contains(this)) throw new IllegalArgumentException("Другой преподаватель курса");
if (courses.contains(course)) throw new IllegalArgumentException("Курс уже назначен");
courses.add(course);

if (faculties.stream().anyMatch(f -> f.getName().equals(name == null ? "" : name.strip())))
    throw new IllegalArgumentException("Факультет уже существует");
Faculty faculty = new Faculty(this, name);
faculties.add(faculty);
return faculty;

if (institute == null || institute.getFaculty().getUniversity() != this)
    throw new IllegalArgumentException("Нужна кафедра этого университета");
if (employees.stream().anyMatch(e -> e.getSocialSecurityNumber().equals(ssn == null ? "" : ssn.strip())))
    throw new IllegalArgumentException("Социальный код уже зарегистрирован");
ResearchEmployee employee = lecturer ? new Lecturer(ssn, name, email, area, institute)
    : new ResearchEmployee(ssn, name, email, area, institute);
employees.add(employee);
return employee;

if (projects.stream().anyMatch(p -> p.getName().equals(name == null ? "" : name.strip())))
    throw new IllegalArgumentException("Проект уже существует");
Project project = new Project(name, start, end);
projects.add(project);
return project;

ResearchEmployee employee = findEmployee(ssn);
if (!projects.contains(project)) throw new IllegalArgumentException("Проект другого университета");
return employee.joinProject(project, hours);

ResearchEmployee employee = findEmployee(ssn);
if (!(employee instanceof Lecturer)) throw new IllegalArgumentException("Сотрудник не является преподавателем");
Lecturer lecturer = (Lecturer) employee;
Course course = courses.stream().filter(c -> c.getId().equals(id == null ? "" : id.strip())).findFirst().orElse(null);
if (course != null) {
    if (!course.getName().equals(name == null ? "" : name.strip()) || course.getWeeklyDuration() != weeklyDuration)
        throw new IllegalArgumentException("ID курса занят другим курсом");
    if (course.getLecturers().contains(lecturer)) throw new IllegalArgumentException("Курс уже назначен преподавателю");
    course.addLecturer(lecturer);
} else {
    course = new Course(id, name, weeklyDuration, lecturer);
    courses.add(course);
}
lecturer.teachCourse(course);
return course;

if (faculties.isEmpty()) throw new IllegalStateException("Нужен хотя бы один факультет");
for (Faculty faculty : faculties) {
    if (faculty.getDean() == null || faculty.getInstitutes().isEmpty())
        throw new IllegalStateException("Нужно назначить декана и создать кафедру: " + faculty.getName());
}
